// Spanish ideas whose whole rule needs words the path brings later. Each part says only what its words let a learner see, and an
// idea's card says the parts whose words you know, so it never names a word you haven't met. A lesson that brings a part's last
// word shows that part as a step of its own (study/idea-parts.js, study/lesson.js). words: lemmas, as the packs name them; name: the
// card's title once that part is known (the grammar's name lists every word, so it would name some before they're met).
export default {
  possessive: [
    { words: ["mi"], name: "mi: words for belonging", line: "mi: my, the same for el and la words" },
    { words: ["tu"], name: "mi, tu: words for belonging", line: "tu: your (to someone you say tú to)" },
  ],
  demonstrative: [
    { words: ["esto", "eso"], name: "esto, eso: this and that", line: "esto and eso: this and that, for a thing you don't name" },
    { words: ["ese"], name: "esto, eso, ese: this and that", line: "ese: that one, for something you could name" },
  ],
};
